package org.freecad.mobilelab;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class FeatureRegression {
 static int checks;interface Action{void run()throws Exception;}
 static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;}
 static void near(double a,double b){check(Math.abs(a-b)<1e-5,"Expected "+b+" got "+a);}
 static void reject(Action a)throws Exception{try{a.run();}catch(Exception x){checks++;return;}throw new AssertionError("Invalid operation accepted");}
 static void tx(Action a)throws Exception{String old=ProjectStore.workspace();NativeCad.beginTransaction(true);try{a.run();NativeCad.setWorkspace(ProjectStore.workspace());NativeCad.commitTransaction();}catch(Throwable x){NativeCad.rollbackTransaction();ProjectStore.applyWorkspace(old);throw x;}}
 static JSONObject obj(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new AssertionError("Object missing");}
 static double volume(int id)throws Exception{return obj(id).getDouble("volume");}
 public static void main(String[] args)throws Exception{
  NativeCad.clear();ProjectStore.reset();int root=NativeCad.create("Rectangle",new double[]{10,6});int pad=FeatureModel.model("Extrude solid",new int[]{root},new double[]{0,0,2});NativeCad.properties(pad,"Pad A","Jewellery",false);NativeCad.setWorkspace(ProjectStore.workspace());near(volume(pad),120);tx(()->FeatureModel.edit(root,new double[]{20,6}));near(volume(pad),240);check(obj(pad).getString("name").equals("Pad A"),"Recompute lost property");check(new JSONArray(NativeCad.objects()).length()==2,"Recompute changed IDs/count");tx(()->FeatureModel.parameters(pad,new double[]{0,0,4}));near(volume(pad),480);NativeCad.undo();ProjectStore.applyWorkspace(NativeCad.getWorkspace());near(volume(pad),240);near(FeatureModel.recipe(pad).getJSONArray("params").getDouble(2),2);NativeCad.redo();ProjectStore.applyWorkspace(NativeCad.getWorkspace());near(volume(pad),480);
  int cutter=NativeCad.create("Cylinder",new double[]{1,10});int cut=FeatureModel.operation("Cut",pad,cutter,0);near(volume(cut),480-4*Math.PI);tx(()->FeatureModel.edit(root,new double[]{24,6}));near(volume(cut),576-4*Math.PI);check(FeatureModel.recipes.length()==2,"DAG records missing");String geometry=NativeCad.objects(),recipes=ProjectStore.workspace();reject(()->tx(()->FeatureModel.parameters(pad,new double[]{0,0,0})));check(geometry.equals(NativeCad.objects())&&recipes.equals(ProjectStore.workspace()),"Failed recompute did not roll back");reject(()->tx(()->FeatureModel.remove(root)));NativeCad.properties(cut,"Locked output","Default",true);reject(()->tx(()->FeatureModel.edit(root,new double[]{26,6})));near(volume(pad),576);NativeCad.properties(cut,"Output","Default",false);
  JSONArray cyclic=new JSONArray().put(new JSONObject().put("output",1).put("kind","Extrude solid").put("inputs",new JSONArray().put(2)).put("params",new JSONArray())).put(new JSONObject().put("output",2).put("kind","Extrude solid").put("inputs",new JSONArray().put(1)).put("params",new JSONArray()));reject(()->FeatureModel.validate(cyclic,null));reject(()->FeatureModel.validate(FeatureModel.recipes,new HashSet<>(Arrays.asList(root,pad))));
  File dir=Files.createTempDirectory("feature-history-").toFile(),cache=new File(dir,"cache");cache.mkdir();try{File project=new File(dir,"history.fcml");ProjectStore.save(project,cache);tx(()->ProjectStore.restore(project,cache));check(FeatureModel.recipes.length()==2,"Features lost on reopening");JSONObject first=FeatureModel.recipes.getJSONObject(0);int savedRoot=first.getJSONArray("inputs").getInt(0),savedPad=first.getInt("output"),savedCut=FeatureModel.recipes.getJSONObject(1).getInt("output");tx(()->FeatureModel.edit(savedRoot,new double[]{28,6}));near(volume(savedPad),672);near(volume(savedCut),672-4*Math.PI);check(cache.list().length==0,"Project cache leak");}finally{ArchiveIO.deleteTree(dir);}
  NativeCad.clear();ProjectStore.reset();int line=NativeCad.curve("Polyline",new double[]{0,0,3,1,10,0,3,1},false,0);int trimmed=FeatureModel.model("Trim curve",new int[]{line},new double[]{.2,.8});near(new JSONObject(NativeCad.analyze(trimmed,3)).getDouble("length"),6);int extended=FeatureModel.model("Extend line",new int[]{line},new double[]{2,2});near(new JSONObject(NativeCad.analyze(extended,3)).getDouble("length"),14);int projected=FeatureModel.model("Project curve",new int[]{line},new double[]{0});near(obj(projected).getJSONArray("bbox").getDouble(2),0);int next=NativeCad.curve("Polyline",new double[]{10,0,3,1,10,5,3,1},false,0);int joined=FeatureModel.model("Join curves",new int[]{line,next},new double[0]);near(new JSONObject(NativeCad.analyze(joined,3)).getDouble("length"),15);reject(()->tx(()->FeatureModel.model("Join curves",new int[]{projected,next},new double[0])));int rect=NativeCad.create("Rectangle",new double[]{10,6});int region=FeatureModel.model("Planar region",new int[]{rect},new double[0]);near(new JSONObject(NativeCad.analyze(region,3)).getDouble("area"),60);int circle=NativeCad.create("Circle",new double[]{5});near(new JSONObject(NativeCad.curvature(circle)).getDouble("maxCurvature"),.2);near(new JSONObject(NativeCad.curvature(line)).getDouble("maxCurvature"),0);
  int box=NativeCad.create("Box",new double[]{10,8,6});JSONObject top=new JSONObject(NativeCad.topology(box));check(top.getJSONArray("edges").length()==12&&top.getJSONArray("faces").length()==6,"Topology map wrong");int fillet=FeatureModel.model("Selected fillet",new int[]{box},new double[]{.3,1});check(volume(fillet)<480&&volume(fillet)>470,"Selected fillet volume");String before=NativeCad.objects();reject(()->tx(()->FeatureModel.edit(box,new double[]{12,8,6})));check(before.equals(NativeCad.objects()),"Changed topology silently reassigned");int shell=FeatureModel.model("Selected shell",new int[]{box},new double[]{.5,6});check(volume(shell)>0&&volume(shell)<480,"Selected-face shell");reject(()->tx(()->FeatureModel.model("Selected fillet",new int[]{box},new double[]{.3,13})));
  int patch=NativeCad.create("NURBS patch",new double[]{20,16,8});JSONObject poles=new JSONObject(NativeCad.surfaceData(patch));check(poles.getInt("u")==3&&poles.getInt("v")==3,"Patch cage dimensions");near(poles.getJSONArray("poles").getJSONArray(4).getDouble(2),8);tx(()->FeatureModel.surfacePole(patch,new double[]{2,2,0,0,12,2}));near(new JSONObject(NativeCad.surfaceData(patch)).getJSONArray("poles").getJSONArray(4).getDouble(2),12);near(new JSONObject(NativeCad.surfaceData(patch)).getJSONArray("poles").getJSONArray(4).getDouble(3),2);NativeCad.undo();ProjectStore.applyWorkspace(NativeCad.getWorkspace());near(new JSONObject(NativeCad.surfaceData(patch)).getJSONArray("poles").getJSONArray(4).getDouble(2),8);int tp=FeatureModel.model("Trim patch",new int[]{patch},new double[]{.25,.75,.25,.75});check(obj(tp).getJSONArray("bounds").getDouble(0)<20,"Patch was not trimmed");reject(()->tx(()->FeatureModel.surfacePole(tp,new double[]{2,2,0,0,10,1})));int full=FeatureModel.model("Untrim patch",new int[]{tp},new double[0]);near(new JSONObject(NativeCad.surfaceData(full)).getJSONArray("poles").getJSONArray(4).getDouble(2),8);
  System.out.println("PASS: "+checks+" feature assertions: DAG propagation, property/ID preservation, Undo/Redo, failed/locked/topology rollback, project remapping, exact curve tools, selected fillet/shell, rational patch editing and trim/untrim");
 }
}
